package main

import (
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// DriveFile describes one local PDF discovered by scanDriveRoot.
type DriveFile struct {
	Path      string `json:"path"`
	Name      string `json:"name"` // filename without extension; display-only for now
	SizeBytes int64  `json:"sizeBytes"`
	PageCount int    `json:"pageCount"`
}

// DriveFileGroup is one subfolder's worth of files. Name is "" for files
// found directly in the scanned root.
type DriveFileGroup struct {
	Name  string      `json:"name"`
	Files []DriveFile `json:"files"`
}

// scanDriveRoot scans root one level deep: PDFs directly in root form a
// single group with Name "", and each immediate subdirectory of root forms
// its own group containing only its direct PDF children. Files that fail to
// parse as PDFs are skipped rather than failing the whole scan.
func scanDriveRoot(root string) ([]DriveFileGroup, error) {
	entries, err := os.ReadDir(root)
	if err != nil {
		return nil, err
	}

	var groups []DriveFileGroup

	rootFiles, err := scanDir(root, entries)
	if err != nil {
		return nil, err
	}
	if len(rootFiles) > 0 {
		groups = append(groups, DriveFileGroup{Name: "", Files: rootFiles})
	}

	var subdirs []string
	for _, e := range entries {
		if e.IsDir() && !strings.HasPrefix(e.Name(), ".") {
			subdirs = append(subdirs, e.Name())
		}
	}
	sort.Strings(subdirs)

	for _, name := range subdirs {
		dir := filepath.Join(root, name)
		subEntries, err := os.ReadDir(dir)
		if err != nil {
			return nil, err
		}
		files, err := scanDir(dir, subEntries)
		if err != nil {
			return nil, err
		}
		if len(files) > 0 {
			groups = append(groups, DriveFileGroup{Name: name, Files: files})
		}
	}

	return groups, nil
}

// scanDir builds the DriveFile list for the PDFs directly within dir's
// entries, sorted alphabetically by filename.
func scanDir(dir string, entries []os.DirEntry) ([]DriveFile, error) {
	var names []string
	for _, e := range entries {
		if e.IsDir() || strings.HasPrefix(e.Name(), ".") || !strings.HasSuffix(strings.ToLower(e.Name()), ".pdf") {
			continue
		}
		names = append(names, e.Name())
	}
	sort.Strings(names)

	files := make([]DriveFile, 0, len(names))
	for _, name := range names {
		path := filepath.Join(dir, name)
		count, err := pdfPageCount(path)
		if err != nil {
			continue // corrupt or non-PDF despite the extension; skip it
		}
		info, err := os.Stat(path)
		if err != nil {
			continue
		}
		files = append(files, DriveFile{
			Path:      path,
			Name:      strings.TrimSuffix(name, filepath.Ext(name)),
			SizeBytes: info.Size(),
			PageCount: count,
		})
	}
	return files, nil
}

