  root: string | null
  groups: DriveFileGroup[]
  loading: boolean
  error: string | null
  pickRoot: () => Promise<void>
}

export function useFileTree(): FileTreeHandle {
  const [root, setRoot] = useState<string | null>(null)
  const [groups, setGroups] = useState<DriveFileGroup[]>([])
