import { Box, Button, Loader, Stack, Text } from '@mantine/core'
import ClippedPath from '../ClippedPath'
import { useFileTree, DriveFile } from './useFileTree'
import { formatFileSize } from '../../utils'

const LEFT_PANEL_WIDTH = 300

export default function DriveUploadMode() {
  const { root, groups, loading, error, pickRoot } = useFileTree()

  return (
    <Box style={{ display: 'flex', height: '100%' }}>
      <Box
        style={{
          width: LEFT_PANEL_WIDTH,
          flexShrink: 0,
          height: '100%',
          overflowY: 'auto',
          borderRight: '1px solid var(--mantine-color-gray-3)',
          padding: 12,
        }}
      >
        <Box mb="sm">
          <ClippedPath path={root} onClick={pickRoot} placeholder="Choose root folder…" />
        </Box>

        {loading && <Loader size="sm" />}
        {error && <Text size="sm" c="red">{error}</Text>}
        {!loading && !error && root && groups.length === 0 && (
          <Text size="sm" c="dimmed">No PDF files found under this folder.</Text>
        )}
        {!loading && !root && (
          <Button size="xs" onClick={pickRoot}>Choose Root Folder</Button>
        )}

        <Stack gap="md" mt="sm">
          {groups.filter(g => g.name !== '').map(group => (
            <Box key={group.name}>
              <Text size="sm" fw={600}>📁 {group.name}</Text>
              <FileList files={group.files} />
            </Box>
          ))}
          {groups.find(g => g.name === '') && (
            <FileList files={groups.find(g => g.name === '')!.files} />
          )}
        </Stack>
      </Box>

      <Box style={{ flex: '0 0 auto', width: 220, height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'var(--mantine-color-gray-1)' }} />

      <Box style={{ flex: 1, height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center' }} />
    </Box>
  )
}

function FileList({ files }: { files: DriveFile[] }) {
  return (
    <Stack gap={6} mt={4}>
      {files.map(file => (
        <Box key={file.path} pl={4}>
          <Text size="sm">📄 {file.name}</Text>
          <Text size="xs" c="dimmed">{file.pageCount} pages · {formatFileSize(file.sizeBytes)}</Text>
        </Box>
      ))}
    </Stack>
  )
}

