export namespace main {

	export class DriveFile {
	    path: string;
	    name: string;
	    sizeBytes: number;
	    pageCount: number;

	    static createFrom(source: any = {}) {
	        return new DriveFile(source);
	    }

	    constructor(source: any = {}) {
	        if ('string' === typeof source) source = JSON.parse(source);
	        this.path = source["path"];
	        this.name = source["name"];
	        this.sizeBytes = source["sizeBytes"];
	        this.pageCount = source["pageCount"];
	    }
	}
	export class DriveFileGroup {
	    name: string;
	    files: DriveFile[];

	    static createFrom(source: any = {}) {
	        return new DriveFileGroup(source);
	    }

	    constructor(source: any = {}) {
	        if ('string' === typeof source) source = JSON.parse(source);
	        this.name = source["name"];
	        this.files = this.convertValues(source["files"], DriveFile);
	    }

		convertValues(a: any, classs: any, asMap: boolean = false): any {
		    if (!a) {
		        return a;
		    }
		    if (a.slice && a.map) {
		        return (a as any[]).map(elem => this.convertValues(elem, classs));
		    } else if ("object" === typeof a) {
		        if (asMap) {
		            for (const key of Object.keys(a)) {
		                a[key] = new classs(a[key]);
		            }
		            return a;
		        }
		        return new classs(a);
		    }
		    return a;
		}
	}
	export class OutputFileSpec {
	    pages: number[];
	    name: string;
	    outDir: string;

	    static createFrom(source: any = {}) {
	        return new OutputFileSpec(source);
	    }

	    constructor(source: any = {}) {
	        if ('string' === typeof source) source = JSON.parse(source);
	        this.pages = source["pages"];
	        this.name = source["name"];
	        this.outDir = source["outDir"];
	    }
	}

}

